import js from "@eslint/js";
import reactHooks from "eslint-plugin-react-hooks";
import { reactRefresh } from "eslint-plugin-react-refresh";
import { defineConfig, globalIgnores } from "eslint/config";
import globals from "globals";
import tseslint from "typescript-eslint";

export default defineConfig([
  // Build output, test artefacts and generated files (pre-flight F16).
  globalIgnores([
    "dist",
    "test-results",
    "e2e/.auth",
    "pnpm-lock.yaml",
    "src/routeTree.gen.ts",
    "src/api/schema.d.ts",
  ]),
  {
    files: ["**/*.{ts,tsx}"],
    extends: [
      js.configs.recommended,
      tseslint.configs.recommendedTypeChecked,
      reactHooks.configs.flat.recommended,
      reactRefresh.configs.vite(),
    ],
    languageOptions: {
      ecmaVersion: 2023,
      globals: globals.browser,
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // TanStack Router redirects and not-founds are thrown from `beforeLoad`/`loader`
      // (its documented pattern); a `Redirect` is a `Response` and a `NotFoundError` a
      // plain object, not an `Error`.
      "@typescript-eslint/only-throw-error": [
        "error",
        {
          allow: [
            { from: "package", package: "@tanstack/router-core", name: "Redirect" },
            { from: "package", package: "@tanstack/router-core", name: "NotFoundError" },
          ],
        },
      ],
      // Every schema imports `z` from `@/lib/zod`, which turns Zod's JIT off
      // before any schema exists (the CSP forbids eval).
      "no-restricted-imports": [
        "error",
        {
          paths: [{ name: "zod", message: 'Import { z } from "@/lib/zod" (jitless config).' }],
          patterns: [
            { group: ["zod/*"], message: 'Import { z } from "@/lib/zod" (jitless config).' },
          ],
        },
      ],
    },
  },
  {
    files: ["src/lib/zod.ts"],
    rules: { "no-restricted-imports": "off" },
  },
  {
    // Route modules export only `Route` and keep their components module-local;
    // the router plugin's code splitting gives those components their own modules
    // for fast refresh, which this rule cannot see.
    files: ["src/routes/**/*.tsx"],
    rules: { "react-refresh/only-export-components": "off" },
  },
  {
    // A provider and its hook share one module (`@/design/theme` is the import path
    // the plan fixes, M2b P9); an edit there reloads the module instead of hot-swapping.
    files: ["src/design/theme.tsx", "src/design/density.tsx"],
    rules: { "react-refresh/only-export-components": "off" },
  },
  {
    // A TipTap extension and its React view (node view, suggestion list) share one
    // module, so the extension can name the view; an edit reloads the editor instead of
    // hot-swapping it.
    files: ["src/editor/html-node.tsx", "src/editor/image-node.tsx", "src/editor/slash-menu.tsx"],
    rules: { "react-refresh/only-export-components": "off" },
  },
  {
    // Generated by the shadcn CLI and kept close to upstream (docs/design/11-admin-ui.md §7).
    files: ["src/components/ui/**/*.tsx", "src/hooks/use-mobile.ts"],
    rules: {
      "react-refresh/only-export-components": "off",
      "react-hooks/set-state-in-effect": "off",
    },
  },
  {
    // The generated shadcn chart types Recharts' payloads as `any` (docs/design/11-admin-ui.md §7).
    files: ["src/components/ui/chart.tsx"],
    rules: {
      "@typescript-eslint/no-unsafe-assignment": "off",
      "@typescript-eslint/no-unsafe-member-access": "off",
      "@typescript-eslint/no-unsafe-argument": "off",
      "@typescript-eslint/restrict-template-expressions": "off",
      "@typescript-eslint/no-unnecessary-type-assertion": "off",
    },
  },
  {
    // Playwright code, not React: fixtures call their `use` callback, and a fixture
    // without dependencies takes `{}` (Playwright requires an object pattern).
    files: ["e2e/**/*.ts", "playwright.config.ts"],
    languageOptions: { globals: globals.node },
    rules: {
      "react-hooks/rules-of-hooks": "off",
      "react-refresh/only-export-components": "off",
      "no-empty-pattern": ["error", { allowObjectPatternsAsParameters: true }],
    },
  },
  {
    files: ["**/*.{js,mjs}", "vite.config.ts", "vitest.config.ts"],
    languageOptions: { globals: globals.node },
  },
  {
    files: ["**/*.{js,mjs}"],
    extends: [js.configs.recommended],
  },
]);
